-- Preserve nominal amounts while migrating the ledger and wallet to USD cents.
ALTER TABLE ads RENAME COLUMN price_pence TO price_cents;
ALTER TABLE fulfilment_intents RENAME COLUMN price_pence TO price_cents;
ALTER TABLE inboxes RENAME COLUMN price_pence TO price_cents;
ALTER TABLE ledger RENAME COLUMN amount_pence TO amount_cents;
