ALTER TABLE orders RENAME COLUMN price_pence TO price_cents;
ALTER TABLE orders RENAME COLUMN customer_refund_pence TO customer_refund_cents;
ALTER TABLE reward_claims RENAME COLUMN amount_pence TO amount_cents;
ALTER TABLE reward_costs RENAME COLUMN cost_pence TO cost_cents;
