ALTER TABLE wallets RENAME COLUMN reserved_pence TO reserved_cents;
CREATE TABLE payments_usd (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,provider VARCHAR(32) NOT NULL,provider_reference VARCHAR(255) UNIQUE,amount_cents BIGINT NOT NULL,currency VARCHAR(3) NOT NULL DEFAULT 'USD',status VARCHAR(32) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,original_currency VARCHAR(3),FOREIGN KEY(user_id) REFERENCES users(id));
INSERT INTO payments_usd (id,user_id,provider,provider_reference,amount_cents,currency,status,created_at,updated_at,original_currency) SELECT id,user_id,provider,provider_reference,amount_pence,'USD',CASE WHEN currency<>'USD' AND status='pending' THEN 'currency_review' ELSE status END,created_at,updated_at,currency FROM payments;
DROP TABLE payments;
ALTER TABLE payments_usd RENAME TO payments;
